-- CHECK 2: Text types: sku VARCHAR(20) UNIQUE, productName NVARCHAR(100)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Product'') AND c.name = N''sku'' AND t.name = N''varchar'' AND c.max_length = 20 AND c.is_nullable = 0) AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Product'') AND c.name = N''productName'' AND t.name = N''nvarchar'' AND c.max_length = 200 AND c.is_nullable = 0)
  AND EXISTS (SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id WHERE i.object_id = OBJECT_ID(N''dbo.Product'') AND i.is_unique = 1 AND i.is_primary_key = 0 AND c.name = N''sku''), 1, 0);
SET @info = N''expected sku VARCHAR(20) NOT NULL UNIQUE and productName NVARCHAR(100) NOT NULL (Vietnamese text needs NVARCHAR)'';',
