WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. Text types: sku VARCHAR(20) UNIQUE, productName NVARCHAR(100) | Kiểu chữ: sku VARCHAR(20) UNIQUE, productName NVARCHAR(100)'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. Text types: sku VARCHAR(20) UNIQUE, productName NVARCHAR(100) | Kiểu chữ: sku VARCHAR(20) UNIQUE, productName NVARCHAR(100)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

