BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Product'') AND c.name = N''price'' AND t.name = N''decimal'' AND c.precision = 12 AND c.scale = 0) AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Product'') AND c.name = N''releaseDate'' AND t.name = N''date'') AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Product'') AND c.name = N''createdAt'' AND t.name = N''datetime2'' AND c.scale = 0), 1, 0);
