ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 4. Defaults work: createdAt is now, isActive is 1 (BIT) | Mặc định chạy: createdAt là lúc này, isActive là 1 (BIT)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

