ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 5. The row was inserted correctly (Vietnamese text intact, id 1) | Dòng được thêm đúng (chữ Việt nguyên vẹn, id 1)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

