ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. An got 1000 and Chi got 1020 — the gap 1010 is normal | An nhận 1000 và Chi nhận 1020 — khoảng hụt 1010 là bình thường', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

