    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 4. An explicit invoiceNo is rejected without IDENTITY_INSERT | Ghi tay invoiceNo bị từ chối khi chưa bật IDENTITY_INSERT'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 4. An explicit invoiceNo is rejected without IDENTITY_INSERT | Ghi tay invoiceNo bị từ chối khi chưa bật IDENTITY_INSERT', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

